<script setup lang="ts">
/**
 * Mekari Cowork — an autonomous AI co-worker surface. Full-screen product (its
 * own dark shell, no ERP chrome). Three states: Home (composer + suggested work),
 * Working (live steps + sources), Completed (grounded briefing).
 *
 * The briefing is generated by Gemini via /api/cowork/plan, grounded on a compact
 * snapshot of the ERP mock DB (HR / CRM / WMS / finance).
 */
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
import { useCoworkContext } from '~/composables/useCoworkContext'

// Renders inside the standard ERP shell (ErpHeader + ErpSidebar) — the default
// layout. Cowork is a workspace within the ERP, not a separate product surface.

const route = useRoute()
const { build } = useCoworkContext()

type State = 'home' | 'working' | 'completed'
const state = ref<State>('home')

interface Step { title: string; detail: string }
interface Finding { title: string; detail: string }
interface Source { name: string; detail: string }
interface SummaryItem { title: string; detail: string; priority: 'High' | 'Medium' | 'Low' }
interface Plan {
  taskTitle: string
  intro: string
  sources: Source[]
  steps: Step[]
  findings: Finding[]
  metric: string
  summary: SummaryItem[]
  alsoPrepared: { title: string; detail: string }[]
}

const prompt = ref('')
const activeTask = ref('')
const plan = ref<Plan | null>(null)
const planSource = ref<'gemini' | 'fallback' | ''>('')
const errorMsg = ref('')

// Live "what Cowork is doing" progression.
const DEFAULT_STEPS: Step[] = [
  { title: 'Read task context', detail: 'Parsing your request and connected products.' },
  { title: 'Review HR (Talenta)', detail: 'Employees, org, contracts and time-off.' },
  { title: 'Review CRM (Qontak)', detail: 'Customers, open deals and orders.' },
  { title: 'Review WMS & finance', detail: 'Stock levels, receivables and payables.' },
  { title: 'Build briefing', detail: 'Prioritising risks, decisions and actions.' },
]
const liveSteps = ref<Step[]>(DEFAULT_STEPS)
const activeStepIndex = ref(0)
let stepTimer: ReturnType<typeof setInterval> | null = null
const apiDone = ref(false)

const progressPct = computed(() => {
  const total = liveSteps.value.length
  if (!total) return 0
  return Math.min(100, Math.round(((activeStepIndex.value) / total) * 100))
})

const greeting = computed(() => {
  const h = new Date().getHours()
  return h < 12 ? 'Good morning' : h < 18 ? 'Good afternoon' : 'Good evening'
})
const todayLabel = computed(() =>
  new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' }),
)

// Suggested work — grounded prompts tuned to what the mock ERP surfaces.
const suggested = [
  { title: 'Prepare my Monday briefing', badge: 'Needs prep', tone: 'needs',
    sub: 'Cross-check HR, CRM, WMS and finance for what needs attention this week.',
    task: 'Prepare my Monday morning briefing. Review HR, CRM, WMS and finance across the ERP and tell me the top things that need my attention this week.' },
  { title: 'Chase overdue receivables', badge: 'Attention', tone: 'needs',
    sub: 'Find overdue invoices and draft reminders for the biggest ones.',
    task: 'Review overdue receivables in finance, identify the largest overdue invoices, and draft payment reminders. Tell me who to chase first.' },
  { title: 'Reorder low-stock SKUs', badge: 'Attention', tone: 'needs',
    sub: 'Check WMS stock against reorder points and propose a purchase plan.',
    task: 'Check WMS stock levels against reorder points, list the SKUs that are low or out of stock, and propose a reorder plan before they block open sales orders.' },
  { title: 'Review the sales pipeline', badge: 'Review', tone: 'working',
    sub: 'Surface stalled deals and the highest-value customers to prioritise.',
    task: 'Review the Qontak sales pipeline and top customers. Surface the open deals worth prioritising and any stalled ones, and suggest next steps.' },
]

const recent = [
  { title: 'Month-end close checklist', sub: 'Reconciled 3 accounts and flagged 2 unmatched statement lines.' },
  { title: 'Headcount & contracts review', sub: 'Found 2 contracts expiring within 60 days across the org.' },
]

function assignTask(task: string) {
  const t = task.trim()
  if (!t) return
  activeTask.value = t
  prompt.value = t
  plan.value = null
  errorMsg.value = ''
  apiDone.value = false
  liveSteps.value = DEFAULT_STEPS
  activeStepIndex.value = 0
  state.value = 'working'
  startSteps()
  fetchPlan(t)
}

function startSteps() {
  if (stepTimer) clearInterval(stepTimer)
  stepTimer = setInterval(() => {
    if (activeStepIndex.value < liveSteps.value.length) {
      activeStepIndex.value += 1
    }
    maybeComplete()
  }, 1500)
}

async function fetchPlan(task: string) {
  try {
    const res = await $fetch<{ plan: Plan; source: 'gemini' | 'fallback' }>('/api/cowork/plan', {
      method: 'POST',
      body: { task, context: build() },
    })
    plan.value = res.plan
    planSource.value = res.source
    // Swap in the model's real step list (keeps the same reveal position).
    if (res.plan?.steps?.length) {
      liveSteps.value = res.plan.steps
      if (activeStepIndex.value > res.plan.steps.length) activeStepIndex.value = res.plan.steps.length
    }
  } catch (err: any) {
    errorMsg.value = 'Cowork could not reach the model. Showing a grounded summary instead.'
  } finally {
    apiDone.value = true
    maybeComplete()
  }
}

// Advance to the briefing only once the steps have finished revealing AND the
// plan has arrived — so the "work" reads as real, never truncated.
function maybeComplete() {
  if (apiDone.value && plan.value && activeStepIndex.value >= liveSteps.value.length) {
    if (stepTimer) { clearInterval(stepTimer); stepTimer = null }
    setTimeout(() => { state.value = 'completed' }, 700)
  }
}

function reset() {
  if (stepTimer) { clearInterval(stepTimer); stepTimer = null }
  state.value = 'home'
  plan.value = null
  activeTask.value = ''
  prompt.value = ''
}

onMounted(() => {
  // Entry from the header search "Cowork" mode: /cowork?task=...&run=1
  const q = route.query
  if (typeof q.task === 'string' && q.task.trim()) {
    prompt.value = q.task
    if (q.run === '1') assignTask(q.task)
  }
})
onBeforeUnmount(() => { if (stepTimer) clearInterval(stepTimer) })

function badgeClass(tone: string) { return `cw-badge cw-badge--${tone}` }
function priorityTone(p: string) { return p === 'High' ? 'needs' : p === 'Medium' ? 'working' : 'done' }
</script>

<template>
  <div class="cw-app">
    <main class="cw-main">
      <!-- ── Home ── -->
      <section v-if="state === 'home'" class="cw-view">
        <p class="cw-eyebrow">{{ todayLabel }}</p>
        <h1 class="cw-h1">{{ greeting }}, Rizal.</h1>
        <p class="cw-lede">Tell Cowork what you want to get done across your ERP.</p>

        <div class="cw-composer">
          <textarea
            v-model="prompt"
            class="cw-prompt"
            rows="3"
            placeholder="e.g. Review overdue invoices and draft reminders for the biggest ones…"
            @keydown.meta.enter="assignTask(prompt)"
          />
          <div class="cw-composer__foot">
            <div class="cw-chips">
              <span class="cw-chip">Talenta</span><span class="cw-chip">Qontak</span>
              <span class="cw-chip">WMS</span><span class="cw-chip">Jurnal</span>
            </div>
            <button class="cw-btn cw-btn--primary" type="button" @click="assignTask(prompt)">Assign task</button>
          </div>
        </div>

        <p class="cw-section-title">Suggested work</p>
        <div class="cw-grid">
          <button v-for="s in suggested" :key="s.title" class="cw-card cw-card--click" type="button" @click="assignTask(s.task)">
            <div class="cw-card__top">
              <div>
                <h3 class="cw-card__title">{{ s.title }}</h3>
                <p class="cw-muted">{{ s.sub }}</p>
              </div>
              <span :class="badgeClass(s.tone)">{{ s.badge }}</span>
            </div>
          </button>
        </div>

        <p class="cw-section-title">Recent work</p>
        <div class="cw-grid">
          <div v-for="r in recent" :key="r.title" class="cw-card">
            <div class="cw-card__top">
              <div>
                <h3 class="cw-card__title">{{ r.title }}</h3>
                <p class="cw-muted">{{ r.sub }}</p>
              </div>
              <span class="cw-badge cw-badge--done">Done</span>
            </div>
          </div>
        </div>
      </section>

      <!-- ── Working ── -->
      <section v-else-if="state === 'working'" class="cw-view">
        <p class="cw-eyebrow">Task workspace</p>
        <div class="cw-workspace">
          <div class="cw-panel">
            <div class="cw-panel__head">
              <div class="cw-titlerow">
                <div>
                  <h2 class="cw-panel__title">{{ plan?.taskTitle ?? activeTask }}</h2>
                  <p class="cw-muted">{{ plan?.intro ?? 'Cowork is reviewing your ERP data and identifying what needs your attention.' }}</p>
                </div>
                <span class="cw-badge cw-badge--working">Working</span>
              </div>
              <div class="cw-progress"><div class="cw-progress__fill" :style="{ width: progressPct + '%' }" /></div>
            </div>
            <div class="cw-panel__body">
              <p class="cw-section-title cw-section-title--tight">What Cowork is doing</p>
              <div class="cw-steps">
                <div
                  v-for="(s, i) in liveSteps"
                  :key="s.title + i"
                  class="cw-step"
                  :class="{ 'cw-step--done': i < activeStepIndex, 'cw-step--active': i === activeStepIndex }"
                >
                  <span class="cw-dot">{{ i < activeStepIndex ? '✓' : i + 1 }}</span>
                  <div>
                    <strong class="cw-step__title">{{ s.title }}</strong>
                    <p class="cw-step__detail">{{ s.detail }}</p>
                  </div>
                </div>
              </div>

              <template v-if="plan?.findings?.length">
                <p class="cw-section-title">Findings so far</p>
                <div v-for="f in plan.findings" :key="f.title" class="cw-finding">
                  <strong class="cw-finding__title">{{ f.title }}</strong>
                  <p class="cw-finding__detail">{{ f.detail }}</p>
                </div>
              </template>
            </div>
          </div>

          <div class="cw-panel">
            <div class="cw-panel__head"><strong>Sources being used</strong></div>
            <div class="cw-panel__body">
              <div class="cw-source-list">
                <div v-for="s in (plan?.sources ?? [])" :key="s.name" class="cw-source">
                  <span>{{ s.name }}</span><span class="cw-source__detail">{{ s.detail }}</span>
                </div>
                <div v-if="!plan" class="cw-source cw-source--pending"><span>Gathering sources…</span><span class="cw-spinner" /></div>
              </div>
              <button v-if="plan" class="cw-btn cw-btn--primary cw-btn--block" type="button" @click="state = 'completed'">View briefing</button>
              <button class="cw-btn cw-btn--ghost cw-btn--block" type="button" @click="reset">Cancel</button>
            </div>
          </div>
        </div>
      </section>

      <!-- ── Completed ── -->
      <section v-else class="cw-view">
        <p class="cw-eyebrow">Task completed</p>
        <div class="cw-panel">
          <div class="cw-result-hero">
            <div class="cw-titlerow">
              <div>
                <h2 class="cw-panel__title">{{ plan?.taskTitle }} — ready</h2>
                <p class="cw-muted">{{ plan?.intro }}</p>
              </div>
              <span class="cw-badge cw-badge--done">Completed</span>
            </div>
            <p class="cw-metric">{{ plan?.metric }}</p>
            <p v-if="planSource === 'fallback'" class="cw-note">{{ errorMsg || 'Grounded summary (model offline).' }}</p>
            <div class="cw-actions">
              <button class="cw-btn cw-btn--primary" type="button">Create action items</button>
              <button class="cw-btn cw-btn--secondary" type="button">Share briefing</button>
            </div>
          </div>
          <div class="cw-panel__body">
            <p class="cw-section-title cw-section-title--tight">Executive summary</p>
            <div class="cw-summary">
              <div v-for="(s, i) in (plan?.summary ?? [])" :key="s.title" class="cw-summary__item">
                <div>
                  <strong class="cw-summary__title">{{ i + 1 }}. {{ s.title }}</strong>
                  <p class="cw-muted">{{ s.detail }}</p>
                </div>
                <span :class="badgeClass(priorityTone(s.priority))">{{ s.priority }}</span>
              </div>
            </div>

            <template v-if="plan?.alsoPrepared?.length">
              <p class="cw-section-title">Cowork also prepared</p>
              <div class="cw-grid">
                <div v-for="a in plan.alsoPrepared" :key="a.title" class="cw-card">
                  <h3 class="cw-card__title">{{ a.title }}</h3>
                  <p class="cw-muted">{{ a.detail }}</p>
                </div>
              </div>
            </template>

            <div class="cw-actions cw-actions--foot">
              <button class="cw-btn cw-btn--primary" type="button" @click="reset">Done</button>
              <button class="cw-btn cw-btn--secondary" type="button" @click="assignTask(activeTask)">Run again</button>
            </div>
          </div>
        </div>
      </section>
    </main>
  </div>
</template>

<style scoped>
