.cw-prompt { width: 100%; border: none; outline: none; resize: vertical; font-family: inherit; font-size: 17px; line-height: 1.55; color: var(--cw-text); padding: 4px 2px 14px; background: none; }
.cw-prompt::placeholder { color: #9aa1ac; }
